CREATE TABLE `sessions` (
	`id` varchar(128) NOT NULL,
	`userId` int NOT NULL,
	`expiresAt` timestamp NOT NULL,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `sessions_id` PRIMARY KEY(`id`)
);
ALTER TABLE `users` DROP INDEX `users_openId_unique`;
ALTER TABLE `users` MODIFY COLUMN `name` text NOT NULL;
ALTER TABLE `users` MODIFY COLUMN `email` varchar(320) NOT NULL;
ALTER TABLE `users` MODIFY COLUMN `role` enum('admin','representante') NOT NULL DEFAULT 'representante';
ALTER TABLE `users` ADD CONSTRAINT `users_email_unique` UNIQUE(`email`);
ALTER TABLE `users` DROP COLUMN `openId`;
ALTER TABLE `users` DROP COLUMN `loginMethod`;

